CREATE TABLE IF NOT EXISTS agent_notes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES agents(id), content TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','pending')), source TEXT NOT NULL CHECK(source IN ('user','agent')), conversation_id BIGINT REFERENCES conversations(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS notes_agent_idx ON agent_notes(agent_id,status);
CREATE TABLE IF NOT EXISTS note_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, agent_id BIGINT NOT NULL REFERENCES agents(id), note_id BIGINT NOT NULL, action TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE agent_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE note_events ENABLE ROW LEVEL SECURITY;

CREATE TABLE IF NOT EXISTS agent_memory_settings (agent_id BIGINT PRIMARY KEY REFERENCES agents(id), enabled INTEGER NOT NULL DEFAULT 1, automatic INTEGER NOT NULL DEFAULT 1);
ALTER TABLE agent_memory_settings ENABLE ROW LEVEL SECURITY;

ALTER TABLE agent_notes ADD COLUMN IF NOT EXISTS evidence TEXT NOT NULL DEFAULT '';
